class Menu{"use strict";navbar=null;menu=null;menuButton=null;constructor(){this.navbar=document.getElementById("navbar"),this.menu=document.getElementById("mobile-menu"),this.menuButton=document.getElementById("mobile-menu-button"),this.menuButton.addEventListener("click",this.toggle.bind(this),!1),window.addEventListener("scroll",this.onScroll.bind(this),!1)}toggle(){this.menu.classList.contains("is-active")?this.hide():this.show()}show(){this.menu.classList.add("is-active"),document.getElementsByTagName("html")[0].classList.add("overflow-hidden","scrollbar-gutter-stable","bg-gray-50")}hide(){this.menu.classList.remove("is-active"),document.getElementsByTagName("html")[0].classList.remove("overflow-hidden","scrollbar-gutter-stable","bg-gray-50")}onScroll(){var e;window.matchMedia("(width >= 64rem)").matches||document.documentElement.scrollTop<10||((e=window.pageYOffset||document.documentElement.scrollTop)>this.lastScrollTop?this.navbar.classList.add("-top-24!"):this.navbar.classList.remove("-top-24!"),this.lastScrollTop=e)}openSubmenu(e){Number.isInteger(e)&&(this.menu.dataset.submenu=e)}closeSubmenu(){delete this.menu.dataset.submenu}}